begin;
create extension if not exists pgtap with schema extensions;
select plan(18);
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('public.document'::regclass,'public.document_summary'::regclass,'public.todo'::regclass)), 'RLS enabled on all tables');
select is((select count(*) from pg_policies where schemaname='public' and tablename in ('document','document_summary','todo')), 0::bigint, 'no access policies');
select ok(not exists (select 1 from unnest(array['anon','authenticated']) r, unnest(array['public.document','public.document_summary','public.todo']) t, unnest(array['SELECT','INSERT','UPDATE','DELETE']) p where has_table_privilege(r,t,p)), 'client roles lack CRUD');
select ok(not exists (select 1 from unnest(array['public.document','public.document_summary','public.todo']) t, unnest(array['SELECT','INSERT','UPDATE','DELETE']) p where not has_table_privilege('service_role',t,p)), 'service role has CRUD');
select has_index('public','document','document_document_date_idx','date index exists');
select has_index('public','todo','todo_pending_document_idx','pending index exists');
select ok((select pg_get_expr(indpred,indrelid) = '(checked = false)' from pg_index where indexrelid='public.todo_pending_document_idx'::regclass), 'pending index is partial');
insert into public.document (source,id,document_date,created_at,updated_at) values ('obsidian','/synthetic/timestamp.md','2024-01-01','2000-01-01','2000-01-01');
insert into public.document_summary (document_source,document_id,summary,created_at,updated_at) values ('obsidian','/synthetic/timestamp.md','synthetic','2000-01-01','2000-01-01');
insert into public.todo (document_source,document_id,id,text,created_at,updated_at) values ('obsidian','/synthetic/timestamp.md','task','synthetic','2000-01-01','2000-01-01');
update public.document set title='synthetic' where id='/synthetic/timestamp.md';
update public.document_summary set summary='synthetic updated' where document_id='/synthetic/timestamp.md';
update public.todo set checked=true where document_id='/synthetic/timestamp.md';
select is((select created_at from public.document where id='/synthetic/timestamp.md'), '2000-01-01'::timestamptz, 'document created_at preserved');
select is((select created_at from public.document_summary where document_id='/synthetic/timestamp.md'), '2000-01-01'::timestamptz, 'summary created_at preserved');
select is((select created_at from public.todo where document_id='/synthetic/timestamp.md'), '2000-01-01'::timestamptz, 'todo created_at preserved');
select is((select updated_at from public.document where id='/synthetic/timestamp.md'), now(), 'document updated_at maintained');
select is((select updated_at from public.document_summary where document_id='/synthetic/timestamp.md'), now(), 'summary updated_at maintained');
select is((select updated_at from public.todo where document_id='/synthetic/timestamp.md'), now(), 'todo updated_at maintained');
set local role service_role;
select lives_ok($$insert into public.document (source,id,document_date) values ('obsidian','/synthetic/service.md','2024-01-01')$$, 'service role inserts through RLS');
select lives_ok($$insert into public.document_summary (document_source,document_id,summary) values ('obsidian','/synthetic/service.md','synthetic')$$, 'service role inserts summary');
select lives_ok($$insert into public.todo (document_source,document_id,id,text) values ('obsidian','/synthetic/service.md','task','synthetic')$$, 'service role inserts task');
select is((select count(*) from public.document where id='/synthetic/service.md'), 1::bigint, 'service role reads');
select lives_ok($$delete from public.document where id='/synthetic/service.md'$$, 'service role deletes');
reset role;
select * from finish();
rollback;
